<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
$id=(int)($_GET['id']??0);$item=one('SELECT br.*,b.title,b.book_id FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.id=? AND br.user_id=? AND br.fulfillment_method="delivery"',[$id,$user['id']]);
if($item&&$item['status']==='in_transit'&&strtotime($item['estimated_delivery'])<=time()){execute("UPDATE borrowings SET status='active',borrowed_at=estimated_delivery,due_date=datetime(estimated_delivery,'+7 days','start of day','+17 hours') WHERE id=?",[$id]);$item=one('SELECT br.*,b.title,b.book_id FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.id=?',[$id]);}
member_start('Pelacakan Pengantaran',$user,'peminjaman.php'); ?>
<section class="member-section"><span class="member-kicker">PENGANTARAN BUKU</span><h1>Pelacakan paket</h1><?php if($item):?><div class="tracking-card"><p><b><?=e($item['title'])?></b> · <?=e($item['book_id'])?></p><p>Nomor resi: <strong><?=e($item['receipt_no'])?></strong></p><p>Alamat tujuan: <?=e($item['delivery_address']??'')?></p><p>Status: <?=e($item['status']==='in_transit'?'Dalam perjalanan':($item['status']==='active'?'Diperkirakan sudah tiba':'Diproses'))?></p><p>Estimasi sampai: <strong><?=date_id($item['estimated_delivery'],true)?></strong></p><ol><li>Pembayaran diterima · <?=date_id($item['paid_at'],true)?></li><li>Paket disiapkan oleh Bookify</li><li>Dalam perjalanan menuju alamat akun</li><li>Estimasi tiba · <?=date_id($item['estimated_delivery'],true)?></li></ol><?php if($item['status']==='active'):?><p>Masa peminjaman dimulai pada estimasi kedatangan. Batas pengembalian: <?=date_id($item['due_date'],true)?>.</p><?php else:?><p>Masa peminjaman dimulai sesuai estimasi kedatangan. Informasi ini mengikuti jadwal estimasi; konfirmasi kurir tidak tersedia di aplikasi.</p><?php endif;?></div><?php else:?><p>Nomor pengantaran tidak ditemukan.</p><?php endif;?></section><?php member_end(); ?>

